using System;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
namespace LastHost.Prototype.Cinematics.A01.Editor { [Serializable] internal sealed class A01SessionData{public SceneSetup[] setups;public string active;public string start;} public static class A01OfficePreviewSession { const string Key="LastHost.A01.PreviewSnapshot"; public static bool HasSnapshot=>!string.IsNullOrEmpty(SessionState.GetString(Key,string.Empty)); public static void CaptureCurrent(){var p=EditorSceneManager.playModeStartScene;SessionState.SetString(Key,JsonUtility.ToJson(new A01SessionData{setups=EditorSceneManager.GetSceneManagerSetup(),active=EditorSceneManager.GetActiveScene().path,start=p?AssetDatabase.GetAssetPath(p):string.Empty}));} public static bool RestoreAndClear(){var j=SessionState.GetString(Key,string.Empty);if(string.IsNullOrEmpty(j))return false;var x=JsonUtility.FromJson<A01SessionData>(j);if(x.setups!=null)EditorSceneManager.RestoreSceneManagerSetup(x.setups);if(!string.IsNullOrEmpty(x.active))EditorSceneManager.SetActiveScene(SceneManager.GetSceneByPath(x.active));EditorSceneManager.playModeStartScene=string.IsNullOrEmpty(x.start)?null:AssetDatabase.LoadAssetAtPath<SceneAsset>(x.start);Clear();return true;} public static void Clear()=>SessionState.EraseString(Key);}}
